export function useSettings(sheetId: string) {
  const now = useReadNow();
  return useQuery({
    queryKey: nowKey(settingsKey(sheetId), now),
    queryFn: () => getJson<Setting[]>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`, now),
  });
}

